func mergeSorted(_ first: [Int], _ second: [Int]) -> [Int] {
    var result: [Int] = []
    var left = 0, right = 0
    while left < first.count && right < second.count {
        if first[left] <= second[right] {
            result.append(first[left]); left += 1
        } else {
            result.append(second[right]); right += 1
        }
    }
    result.append(contentsOf: first[left...])
    result.append(contentsOf: second[right...])
    return result
}
assert(mergeSorted([1, 4], [2, 4]) == [1, 2, 4, 4])
assert(mergeSorted([], [2]) == [2])

В ответ попадает минимальный из непрочитанных элементов. Остаток уже отсортирован и добавляется без нового выбора.

func moveZeros(_ values: inout [Int]) {
    var write = 0
    for read in values.indices {
        if values[read] != 0 {
            values[write] = values[read]
            write += 1
        }
    }
    for index in write..<values.count { values[index] = 0 }
}
var values = [0, 3, 0, 2]
moveZeros(&values)
assert(values == [3, 2, 0, 0])

write собирает ненулевой префикс, затем хвост заполняется нулями. read никогда не читает уже испорченные будущие позиции.

func isSubsequence(_ small: String, of large: String) -> Bool {
    let required = Array(small)
    var read = 0
    for character in large {
        if read < required.count && required[read] == character { read += 1 }
    }
    return read == required.count
}
assert(isSubsequence("👨‍👩‍👧‍👦Б", of: "А👨‍👩‍👧‍👦Б"))
assert(isSubsequence("", of: "abc"))
assert(!isSubsequence("ба", of: "аб"))

